package com.exito.chop;
/** Original approximation of Analog Heat MKII's processing categories. No Elektron code. */
final class Heat {
 static final String[] CIRCUITS={"OFF","Clean Boost","Saturation","Enhancement","Mid Drive","Rough Crunch","Classic Dist","Round Fuzz","High Gain"};
 static final String[] FILTERS={"OFF","Low-pass 2","High-pass 2","Band-pass","Notch","Peak","Low-pass 1","High-pass 1"};
 static final class Settings {volatile int circuit=0,filter=0,envMode=0,lfoWave=0,lfoMode=0;volatile float drive=.35f,frequency=.65f,resonance=.15f,low=0,high=0,wet=1,mix=1,output=1,dirt=0,pan=0,envDepth=0,attack=.05f,release=.2f,threshold=.12f,lfoDepth=0,lfoRate=.25f;volatile boolean sync=false;}
 final int sr;final Filters.Svf[] filter={new Filters.Svf(),new Filters.Svf()};double lowL,lowR,env,lfo,held,previous;boolean gate;int envStage;int random=92153;
 Heat(int rate){sr=rate;}void reset(){lowL=lowR=env=lfo=previous=0;gate=false;envStage=0;for(Filters.Svf f:filter)f.clear();}
 double noise(){random^=random<<13;random^=random>>>17;random^=random<<5;return random/(double)Integer.MAX_VALUE;}
 static double curve(double x,int kind,double drive){double g=1+drive*24;switch(kind){case 1:return x*(1+drive*2);case 2:return Math.tanh(x*(1+drive*5));case 3:return x+Math.tanh(x*g)*.25;case 4:return Math.atan(x*g)*.7;case 5:return Math.max(-.8,Math.min(.8,x*g));case 6:return Math.tanh((x+.09)*g)-Math.tanh(.09*g);case 7:return Math.tanh(x*g)*Math.min(1,Math.abs(x)*20+drive);case 8:return Math.sin(Math.tanh(x*g)*1.7);default:return x;}}
 void process(float[] data,int samples,Settings s,int bpm){if(s.circuit==0)return;double a=Math.exp(-1/(sr*(.001+s.attack*.3))),r=Math.exp(-1/(sr*(.01+s.release*1.5))),lowAlpha=1-Math.exp(-2*Math.PI*220/sr),hz=s.sync?bpm/60.*Math.pow(2,Math.round(s.lfoRate*6)-3):.03*Math.pow(800,s.lfoRate);
 for(int i=0;i<samples;i+=2){double level=Math.max(Math.abs(data[i]),Math.abs(data[i+1]));boolean now=level>s.threshold,rising=now&&!gate;if(rising&&s.lfoMode==1)lfo=0;if(rising&&s.envMode==2)envStage=1;gate=now;double target=s.envMode==0?level:s.envMode==1?(gate?1:0):(envStage==1?1:0);double coefficient=target>env?a:r;env=coefficient*env+(1-coefficient)*target;if(s.envMode==2&&envStage==1&&env>.98)envStage=2;if(s.envMode==2&&envStage==2&&env<.0001)envStage=0;lfo+=hz/sr;if(lfo>=1){lfo-=Math.floor(lfo);held=noise();}double mod=s.lfoWave==0?Math.sin(lfo*2*Math.PI):s.lfoWave==1?1-4*Math.abs(lfo-.5):s.lfoWave==2?2*lfo-1:s.lfoWave==3?1-2*lfo:s.lfoWave==4?(lfo<.5?1:-1):s.lfoWave==5?held:noise();double frequency=20*Math.pow(900,Math.max(0,Math.min(1,s.frequency+env*s.envDepth*.45+mod*s.lfoDepth*.35)));
 for(int c=0;c<2;c++){double x=data[i+c],v=x;if(c==0){lowL+=lowAlpha*(x-lowL);v=lowL*Math.pow(10,s.low/20.)+(x-lowL)*Math.pow(10,s.high/20.);}else{lowR+=lowAlpha*(x-lowR);v=lowR*Math.pow(10,s.low/20.)+(x-lowR)*Math.pow(10,s.high/20.);}v+=noise()*s.dirt*.002;double y=curve(v,s.circuit,s.drive)*.72;if(s.filter>0)y=filter[c].tick(y,frequency*Math.pow(2,(c==0?-1:1)*s.pan*.3),s.resonance,s.filter,sr);double out=(x+(y*s.wet-x)*s.mix)*s.output;data[i+c]=(float)(Double.isFinite(out)?Math.max(-4,Math.min(4,out)):0);}}
 }
}
